//! Liberty → Synopsys `.db` (docs/tools/pdks.md §4): Design Compiler links only `.db`,
//! neither kit ships one, so `lc_shell` compiles each `.lib`. `write_lib` takes the Liberty
//! `library (NAME)`, not the file name (`write_lib(2)`), so the name is read from each file.

use std::io::Read;
use std::path::{Path, PathBuf};

use cc_core::config::PdkConfig;
use cc_core::{CoreError, Result};

/// One Liberty file to compile: its path and its `library (NAME)`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LibertyLib {
    pub path: PathBuf,
    pub name: String,
}

impl LibertyLib {
    pub fn db_file(&self) -> String {
        format!("{}.db", self.name)
    }
}

/// The name in the first `library ( NAME )` group, quotes stripped.
pub fn library_name(text: &str) -> Option<String> {
    text.lines().find_map(|line| {
        let rest = line.trim_start().strip_prefix("library")?.trim_start();
        let inner = rest.strip_prefix('(')?;
        let name = inner[..inner.find(')')?].trim().trim_matches('"').trim();
        (!name.is_empty()).then(|| name.to_string())
    })
}

/// Read only the header: the `library` group opens in the first lines and ASAP7 files are ~20 MB.
pub fn read_library(path: &Path) -> Result<LibertyLib> {
    let io = |source| CoreError::Io {
        path: path.to_path_buf(),
        source,
    };
    let mut buf = Vec::new();
    std::fs::File::open(path)
        .map_err(io)?
        .take(256 * 1024)
        .read_to_end(&mut buf)
        .map_err(io)?;
    let name = library_name(&String::from_utf8_lossy(&buf)).ok_or_else(|| CoreError::Artifact {
        kind: "pdk_db".into(),
        message: format!(
            "{}: no `library (NAME)` group in the first 256 KiB",
            path.display()
        ),
    })?;
    Ok(LibertyLib {
        path: path.to_path_buf(),
        name,
    })
}

/// The ASAP7 NLDM files of one VT/corner, one per cell group, in `pdk.asap7_groups` order. File
/// names carry different date stamps per group (`asap7sc7p5t_<G>_<VT>_<C>_nldm_<date>.lib`), so the
/// stamp is matched, not assumed. Exactly one file per group, or an error.
pub fn asap7_libs(nldm_dir: &Path, pdk: &PdkConfig) -> Result<Vec<PathBuf>> {
    let entries: Vec<String> = std::fs::read_dir(nldm_dir)
        .map_err(|source| CoreError::Io {
            path: nldm_dir.to_path_buf(),
            source,
        })?
        .filter_map(|e| e.ok()?.file_name().into_string().ok())
        .collect();
    let mut out = Vec::new();
    for g in &pdk.asap7_groups {
        let prefix = format!("asap7sc7p5t_{g}_{}_{}_nldm_", pdk.asap7_vt, pdk.asap7_corner);
        let mut hits: Vec<&String> = entries
            .iter()
            .filter(|n| n.starts_with(&prefix) && n.ends_with(".lib"))
            .collect();
        hits.sort();
        match hits.as_slice() {
            [one] => out.push(nldm_dir.join(one)),
            _ => {
                return Err(CoreError::Artifact {
                    kind: "pdk_db".into(),
                    message: format!(
                        "{}: expected one {prefix}*.lib, found {}",
                        nldm_dir.display(),
                        hits.len()
                    ),
                });
            }
        }
    }
    Ok(out)
}

/// `lc_shell -f` script: `read_lib` + `write_lib` per library, then `quit` (synopsys.md §3).
pub fn make_db_tcl(libs: &[LibertyLib]) -> String {
    let mut s = String::from("# Generated by chipc doctor: Liberty -> .db for Design Compiler.\n");
    for l in libs {
        s.push_str(&format!(
            "read_lib {}\nwrite_lib {} -format db -output {}\n",
            tcl_word(&l.path.display().to_string()),
            l.name,
            l.db_file()
        ));
    }
    s.push_str("quit\n");
    s
}

/// Brace-quote a Tcl word when it contains anything but plain path characters.
pub(crate) fn tcl_word(s: &str) -> String {
    if s.chars()
        .all(|c| c.is_ascii_alphanumeric() || "/._-+".contains(c))
    {
        s.to_string()
    } else {
        format!("{{{s}}}")
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn library_name_forms() {
        assert_eq!(
            library_name("/* x */\nlibrary (NangateOpenCellLibrary) {\n"),
            Some("NangateOpenCellLibrary".into())
        );
        assert_eq!(library_name("  library(\"lib_a\"){"), Some("lib_a".into()));
        assert_eq!(library_name("cell (library) {"), None);
        assert_eq!(library_name("no header"), None);
    }

    #[test]
    fn asap7_selection_matches_each_group_once() {
        let d = tempfile::tempdir().unwrap();
        for f in [
            "asap7sc7p5t_AO_RVT_TT_nldm_211120.lib",
            "asap7sc7p5t_AO_RVT_TT_nldm_211120.lib.7z",
            "asap7sc7p5t_SEQ_RVT_TT_nldm_220123.lib",
            "asap7sc7p5t_SEQ_LVT_TT_nldm_220123.lib",
            "asap7sc7p5t_SEQ_RVT_FF_nldm_220123.lib",
        ] {
            std::fs::write(d.path().join(f), "").unwrap();
        }
        let pdk = PdkConfig {
            asap7_groups: vec!["AO".into(), "SEQ".into()],
            ..PdkConfig::default()
        };
        let libs = asap7_libs(d.path(), &pdk).unwrap();
        let names: Vec<_> = libs
            .iter()
            .map(|p| p.file_name().unwrap().to_str().unwrap())
            .collect();
        assert_eq!(
            names,
            [
                "asap7sc7p5t_AO_RVT_TT_nldm_211120.lib",
                "asap7sc7p5t_SEQ_RVT_TT_nldm_220123.lib"
            ]
        );
        let missing = PdkConfig {
            asap7_groups: vec!["OA".into()],
            ..PdkConfig::default()
        };
        assert!(asap7_libs(d.path(), &missing).is_err());
    }

    #[test]
    fn make_db_script_uses_library_names() {
        let tcl = make_db_tcl(&[LibertyLib {
            path: "/p/stdcells.lib".into(),
            name: "NangateOpenCellLibrary".into(),
        }]);
        assert_eq!(
            tcl.lines().skip(1).collect::<Vec<_>>(),
            [
                "read_lib /p/stdcells.lib",
                "write_lib NangateOpenCellLibrary -format db -output NangateOpenCellLibrary.db",
                "quit"
            ]
        );
    }
}
